// Byte-string primitives.
//
// A "byte string" is modelled as a JS string in which every code unit is a
// single octet (0..255). This keeps the whole library free of typed-array
// machinery while still giving exact byte-level semantics: length is a byte
// count, concatenation is byte concatenation, and slicing is byte slicing.

const ASCII_PRINTABLE_LOW = 0x20;
const ASCII_PRINTABLE_HIGH = 0x7e;

/** Encode text to its UTF-8 octets, returned as a one-octet-per-code-unit string. */
export function textToOctets(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out += String.fromCharCode(cp);
    } else if (cp < 0x800) {
      out += String.fromCharCode(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out += String.fromCharCode(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    } else {
      out += String.fromCharCode(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/** Decode UTF-8 octets back to text, tolerating malformed input byte-wise. */
export function octetsToText(octets) {
  let out = '';
  let i = 0;
  while (i < octets.length) {
    const b0 = octets.charCodeAt(i);
    let cp;
    let size;
    if (b0 < 0x80) {
      cp = b0;
      size = 1;
    } else if (b0 >= 0xc0 && b0 < 0xe0) {
      cp = b0 & 0x1f;
      size = 2;
    } else if (b0 >= 0xe0 && b0 < 0xf0) {
      cp = b0 & 0x0f;
      size = 3;
    } else if (b0 >= 0xf0) {
      cp = b0 & 0x07;
      size = 4;
    } else {
      out += '�';
      i += 1;
      continue;
    }
    if (i + size > octets.length) {
      out += '�';
      i += 1;
      continue;
    }
    for (let k = 1; k < size; k++) cp = (cp << 6) | (octets.charCodeAt(i + k) & 0x3f);
    out += String.fromCodePoint(cp);
    i += size;
  }
  return out;
}

/**
 * Render octets the way CPython renders `bytes`: `b'...'`, switching to double
 * quotes when the payload contains a single quote but no double quote.
 */
export function octetsRepr(octets) {
  const quote = octets.includes("'") && !octets.includes('"') ? '"' : "'";
  let body = '';
  for (let i = 0; i < octets.length; i++) {
    const ch = octets[i];
    const code = octets.charCodeAt(i);
    if (ch === '\\') body += '\\\\';
    else if (ch === quote) body += '\\' + ch;
    else if (ch === '\t') body += '\\t';
    else if (ch === '\n') body += '\\n';
    else if (ch === '\r') body += '\\r';
    else if (code < ASCII_PRINTABLE_LOW || code > ASCII_PRINTABLE_HIGH) {
      body += '\\x' + code.toString(16).padStart(2, '0');
    } else body += ch;
  }
  return `b${quote}${body}${quote}`;
}

/** An immutable byte string, the JS stand-in for CPython's `bytes`. */
export class PyBytes {
  constructor(octets = '') {
    this.octets = octets;
  }

  static fromText(text) {
    return new PyBytes(textToOctets(text));
  }

  /** Accept a PyBytes or plain text and normalise to PyBytes. */
  static coerce(value) {
    if (value instanceof PyBytes) return value;
    if (typeof value === 'string') return PyBytes.fromText(value);
    throw new TypeError('cannot interpret value as a byte string');
  }

  get length() {
    return this.octets.length;
  }

  byteAt(index) {
    return this.octets.charCodeAt(index);
  }

  slice(start, end) {
    return new PyBytes(this.octets.slice(start, end));
  }

  concat(other) {
    return new PyBytes(this.octets + PyBytes.coerce(other).octets);
  }

  toText() {
    return octetsToText(this.octets);
  }

  repr() {
    return octetsRepr(this.octets);
  }

  toString() {
    return this.repr();
  }
}

/** Join a list of PyBytes into one. */
export function joinBytes(parts) {
  let octets = '';
  for (const part of parts) octets += PyBytes.coerce(part).octets;
  return new PyBytes(octets);
}

