// CPython `int()` semantics for base-10 text, backed by BigInt so that
// arbitrary-precision arithmetic matches Python exactly.

/** Raised where CPython would raise ValueError. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

// Characters for which CPython's str.isspace() is true and which therefore get
// stripped by int(). JS \s covers the spaces/BOM/NBSP; the rest are the C0
// separators Python also treats as whitespace.
const PY_SPACE = '[\\s\\u001c\\u001d\\u001e\\u001f\\u0085]';
const STRIP_RE = new RegExp(`^${PY_SPACE}+|${PY_SPACE}+$`, 'g');

// int() allows single underscores strictly between digits: 1_000 is fine,
// while _1, 1_ and 1__0 are all rejected.
const INT_LITERAL_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/;

/** CPython str.strip() with no argument. */
export function pyStrip(text) {
  return text.replace(STRIP_RE, '');
}

/**
 * Convert text to a BigInt using CPython's base-10 `int()` rules.
 * Throws PyValueError on anything CPython would reject.
 */
export function pyInt(text) {
  const stripped = pyStrip(text);
  if (!INT_LITERAL_RE.test(stripped)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyStrRepr(text)}`,
    );
  }
  const digits = stripped.replace(/_/g, '');
  return BigInt(digits[0] === '+' ? digits.slice(1) : digits);
}

/** Render text the way CPython renders `str` in a repr context. */
export function pyStrRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let body = '';
  for (const ch of text) {
    if (ch === '\\') body += '\\\\';
    else if (ch === quote) body += '\\' + ch;
    else if (ch === '\t') body += '\\t';
    else if (ch === '\n') body += '\\n';
    else if (ch === '\r') body += '\\r';
    else {
      const code = ch.codePointAt(0);
      if (code < 0x20 || code === 0x7f) body += '\\x' + code.toString(16).padStart(2, '0');
      else body += ch;
    }
  }
  return `${quote}${body}${quote}`;
}

