// Bencode serialiser. Reimplemented from observed interface behaviour:
//   integers  -> i<decimal>e          (arbitrary precision, sign preserved)
//   bytes     -> <bytelength>:<bytes>
//   lists     -> l<items>e
//   dicts     -> d<key><value>...e    (keys sorted as raw byte strings)

import { PyBytes, joinBytes } from '../bytes.mjs';

/** Raised where CPython's encoder would reject an unsupported object. */
export class BencodeEncodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BencodeEncodeError';
  }
}

function encodeInteger(value) {
  return new PyBytes(`i${value.toString()}e`);
}

function encodeBytes(value) {
  return new PyBytes(`${value.length}:${value.octets}`);
}

function encodeList(items) {
  const parts = [new PyBytes('l')];
  for (const item of items) parts.push(encode(item));
  parts.push(new PyBytes('e'));
  return joinBytes(parts);
}

function dictEntries(value) {
  if (value instanceof Map) return [...value.entries()];
  return Object.entries(value);
}

function encodeDict(value) {
  const entries = dictEntries(value).map(([key, item]) => [PyBytes.coerce(key), item]);
  // Bencode requires keys in lexicographic byte order.
  entries.sort((left, right) => {
    if (left[0].octets < right[0].octets) return -1;
    if (left[0].octets > right[0].octets) return 1;
    return 0;
  });
  const parts = [new PyBytes('d')];
  for (const [key, item] of entries) {
    parts.push(encodeBytes(key));
    parts.push(encode(item));
  }
  parts.push(new PyBytes('e'));
  return joinBytes(parts);
}

/** Encode a Python-ish value to a PyBytes byte string. */
export function encode(value) {
  if (typeof value === 'bigint') return encodeInteger(value);
  if (typeof value === 'boolean') return encodeInteger(value ? 1n : 0n);
  if (typeof value === 'number') {
    if (!Number.isInteger(value)) {
      throw new BencodeEncodeError(`value ${value} is not an integer`);
    }
    return encodeInteger(BigInt(value));
  }
  if (value instanceof PyBytes) return encodeBytes(value);
  if (typeof value === 'string') return encodeBytes(PyBytes.fromText(value));
  if (Array.isArray(value)) return encodeList(value);
  if (value instanceof Set) return encodeList([...value]);
  if (value !== null && typeof value === 'object') return encodeDict(value);
  throw new BencodeEncodeError(`cannot bencode value of type ${typeof value}`);
}

