// Bencode parser. Integers come back as BigInt, byte strings as PyBytes,
// lists as arrays and dicts as Map, mirroring the Python objects the reference
// decoder hands back.

import { PyBytes } from '../bytes.mjs';

/** Raised where CPython's decoder would reject malformed input. */
export class BencodeDecodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BencodeDecodeError';
  }
}

const INTEGER_BODY_RE = /^(?:0|-?[1-9][0-9]*)$/;
const LENGTH_RE = /^(?:0|[1-9][0-9]*)$/;

class Reader {
  constructor(octets) {
    this.octets = octets;
    this.pos = 0;
  }

  peek() {
    if (this.pos >= this.octets.length) {
      throw new BencodeDecodeError('unexpected end of bencoded data');
    }
    return this.octets[this.pos];
  }

  take(count) {
    if (this.pos + count > this.octets.length) {
      throw new BencodeDecodeError('unexpected end of bencoded data');
    }
    const chunk = this.octets.slice(this.pos, this.pos + count);
    this.pos += count;
    return chunk;
  }

  readUntil(terminator) {
    const at = this.octets.indexOf(terminator, this.pos);
    if (at === -1) {
      throw new BencodeDecodeError(`missing ${JSON.stringify(terminator)} terminator`);
    }
    const chunk = this.octets.slice(this.pos, at);
    this.pos = at + 1;
    return chunk;
  }
}

function readInteger(reader) {
  reader.take(1); // consume 'i'
  const body = reader.readUntil('e');
  if (!INTEGER_BODY_RE.test(body)) {
    throw new BencodeDecodeError(`invalid bencoded integer: ${JSON.stringify(body)}`);
  }
  return BigInt(body);
}

function readByteString(reader) {
  const rawLength = reader.readUntil(':');
  if (!LENGTH_RE.test(rawLength)) {
    throw new BencodeDecodeError(`invalid byte string length: ${JSON.stringify(rawLength)}`);
  }
  return new PyBytes(reader.take(Number(rawLength)));
}

function readList(reader) {
  reader.take(1); // consume 'l'
  const items = [];
  while (reader.peek() !== 'e') items.push(readValue(reader));
  reader.take(1); // consume 'e'
  return items;
}

function readDict(reader) {
  reader.take(1); // consume 'd'
  const mapping = new Map();
  while (reader.peek() !== 'e') {
    const key = readByteString(reader);
    mapping.set(key, readValue(reader));
  }
  reader.take(1); // consume 'e'
  return mapping;
}

function readValue(reader) {
  const marker = reader.peek();
  if (marker === 'i') return readInteger(reader);
  if (marker === 'l') return readList(reader);
  if (marker === 'd') return readDict(reader);
  if (marker >= '0' && marker <= '9') return readByteString(reader);
  throw new BencodeDecodeError(`unexpected marker ${JSON.stringify(marker)}`);
}

/** Decode a PyBytes (or text) payload into Python-ish values. */
export function decode(payload) {
  const reader = new Reader(PyBytes.coerce(payload).octets);
  const value = readValue(reader);
  if (reader.pos !== reader.octets.length) {
    throw new BencodeDecodeError('trailing data after bencoded value');
  }
  return value;
}

