  if (marker === 'i') return readInteger(reader);
  if (marker === 'l') return readList(reader);
  if (marker === 'd') return readDict(reader);
  if (marker >= '0' && marker <= '9') return readByteString(reader);
  throw new BencodeDecodeError(`unexpected marker ${JSON.stringify(marker)}`);
