/** Decode a PyBytes (or text) payload into Python-ish values. */
export function decode(payload) {
  const reader = new Reader(PyBytes.coerce(payload).octets);
  const value = readValue(reader);
  if (reader.pos !== reader.octets.length) {
    throw new BencodeDecodeError('trailing data after bencoded value');
  }
