// A focused reimplementation of the pieces of CPython's `argparse` this program
// relies on: long options with a single value, `-h/--help`, prefix
// abbreviation, the negative-number heuristic, `--` handling, required-argument
// checking and the exact usage/error/help wording (stderr + exit code 2).

import { PyValueError, pyStrRepr } from './pyint.mjs';

// argparse._negative_number_matcher: when the parser defines no option that
// itself looks like a negative number, tokens matching this are values.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

const MAX_HELP_POSITION = 24;

class ParserExit extends Error {
  constructor(status) {
    super(`parser exit ${status}`);
    this.status = status;
  }
}

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(optionStrings, { action = 'store', type, required = false, dest, metavar, help } = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    // dest comes from the first long option, with leading dashes removed.
    const longest = strings.find((s) => s.startsWith('--')) ?? strings[0];
    const resolvedDest = dest ?? longest.replace(/^-+/, '').replace(/-/g, '_');
    const entry = {
      optionStrings: strings,
      action,
      type,
      required,
      dest: resolvedDest,
      metavar: metavar ?? resolvedDest.toUpperCase(),
      help,
    };
    this.actions.push(entry);
    for (const s of strings) this.optionStringActions.set(s, entry);
    return entry;
  }

  // ---- usage / help rendering -------------------------------------------

  formatUsage() {
    const parts = this.actions.map((entry) => {
      const base =
        entry.action === 'help'
          ? entry.optionStrings[0]
          : `${entry.optionStrings[0]} ${entry.metavar}`;
      return entry.required ? base : `[${base}]`;
    });
    return `usage: ${this.prog}${parts.length ? ' ' + parts.join(' ') : ''}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((entry) =>
      entry.action === 'help'
        ? entry.optionStrings.join(', ')
        : `${entry.optionStrings[0]} ${entry.metavar}`,
    );
    // argparse: action_max_length includes the 2-space indent, then help text
    // starts two columns further right, capped at max_help_position.
    const actionMaxLength = Math.max(0, ...invocations.map((s) => s.length)) + 2;
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    let out = this.formatUsage();
    out += '\noptions:\n';
    this.actions.forEach((entry, index) => {
      const head = '  ' + invocations[index];
      if (!entry.help) {
        out += head + '\n';
      } else if (head.length < helpPosition) {
        out += head.padEnd(helpPosition) + entry.help + '\n';
      } else {
        out += head + '\n' + ' '.repeat(helpPosition) + entry.help + '\n';
      }
    });
    return out;
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  exit(status = 0) {
    throw new ParserExit(status);
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    this.exit(2);
  }

  // ---- option recognition ------------------------------------------------

  get hasNegativeNumberOptionals() {
    return [...this.optionStringActions.keys()].some((s) => NEGATIVE_NUMBER_RE.test(s));
  }

  /**
   * Classify a token. Returns null when the token is a plain value, otherwise
   * [action|null, optionString, explicitArg|null]; a null action means the
   * token looks like an option but matches nothing we defined.
   */
  parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null; // a bare "-" is a value

    if (argString.includes('=')) {
      const at = argString.indexOf('=');
      const head = argString.slice(0, at);
      const explicitArg = argString.slice(at + 1);
      if (this.optionStringActions.has(head)) {
        return [this.optionStringActions.get(head), head, explicitArg];
      }
    }

    const matches = this.matchAbbreviation(argString);
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      const names = matches.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }

    if (NEGATIVE_NUMBER_RE.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  /** argparse._get_option_tuples: unique-prefix abbreviation of long options. */
  matchAbbreviation(argString) {
    if (!argString.startsWith('--')) return [];
    const at = argString.indexOf('=');
    const head = at === -1 ? argString : argString.slice(0, at);
    const explicitArg = at === -1 ? null : argString.slice(at + 1);
    const result = [];
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(head)) result.push([action, optionString, explicitArg]);
    }
    return result;
  }

  looksLikeOption(argString) {
    return argString !== undefined && this.parseOptional(argString) !== null;
  }

  // ---- parsing -----------------------------------------------------------

  convert(entry, optionString, rawValue) {
    if (!entry.type) return rawValue;
    try {
      return entry.type.fn(rawValue);
    } catch (err) {
      if (err instanceof PyValueError || err instanceof TypeError) {
        this.error(
          `argument ${optionString}: invalid ${entry.type.name} value: ${pyStrRepr(rawValue)}`,
        );
      }
      throw err;
    }
  }

  parseKnownArgs(argStrings) {
    const namespace = Object.create(null);
    for (const entry of this.actions) {
      if (entry.action !== 'help') namespace[entry.dest] = null;
    }

    const extras = [];
    const seen = new Set();
    let separatorSeen = false;
    let i = 0;

    while (i < argStrings.length) {
      const arg = argStrings[i];

      // Everything from the first "--" onward can only feed positionals; this
      // program defines none, so those tokens all end up unrecognized -- and
      // the "--" itself is reported too, matching argparse.
      if (separatorSeen) {
        extras.push(arg);
        i += 1;
        continue;
      }
      if (arg === '--') {
        separatorSeen = true;
        extras.push(arg);
        i += 1;
        continue;
      }

      const option = this.parseOptional(arg);
      if (option === null || option[0] === null) {
        extras.push(arg);
        i += 1;
        continue;
      }

      const [entry, optionString, explicitArg] = option;
      i += 1;

      if (entry.action === 'help') {
        this.printHelp();
        this.exit(0);
      }

      let rawValue;
      if (explicitArg !== null && explicitArg !== undefined) {
        rawValue = explicitArg;
      } else {
        const next = argStrings[i];
        if (next === undefined || next === '--' || this.looksLikeOption(next)) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        rawValue = next;
        i += 1;
      }

      namespace[entry.dest] = this.convert(entry, optionString, rawValue);
      seen.add(entry);
    }

    const missing = this.actions
      .filter((entry) => entry.required && !seen.has(entry))
      .map((entry) => entry.optionStrings[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parseArgs(argStrings) {
    const [namespace, extras] = this.parseKnownArgs(argStrings);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

export { ParserExit };

