// Entry point: port of dataset/bencoder/test14.py
//
// Mirrors the original line for line -- same argument surface (--a and --b,
// both required ints), same four printed lines, and Python's unbounded integer
// arithmetic via BigInt.

import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { ArgumentParser, ParserExit } from './lib/argparse.mjs';
import { int } from './lib/argtypes.mjs';
import * as bencoder from './lib/bencode/index.mjs';
import { pyPrint } from './lib/pyrepr.mjs';

function main(argv) {
  // argparse defaults prog to basename(sys.argv[0]).
  const prog = path.basename(fileURLToPath(import.meta.url));

  const parser = new ArgumentParser({ prog });
  parser.addArgument(['--a'], { type: int, required: true });
  parser.addArgument(['--b'], { type: int, required: true });
  const args = parser.parseArgs(argv);

  const numbers = [args.a, args.b, args.a + args.b, args.a * args.b];
  const encoded = bencoder.encode(numbers); // Encode list of numbers
  const decoded = bencoder.decode(encoded); // Decode numbers
  const encodedNegative = bencoder.encode(-args.a); // Encode negative number
  const encodedZero = bencoder.encode(0n); // Encode zero
  pyPrint(encoded);
  pyPrint(decoded);
  pyPrint(encodedNegative);
  pyPrint(encodedZero);
}

try {
  main(process.argv.slice(2));
} catch (err) {
  if (err instanceof ParserExit) {
    process.exit(err.status);
  }
  throw err;
}

