// while _1, 1_ and 1__0 are all rejected.
const INT_LITERAL_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/;

/** CPython str.strip() with no argument. */
export function pyStrip(text) {
  return text.replace(STRIP_RE, '');
}

/**
 * Convert text to a BigInt using CPython's base-10 `int()` rules.
 * Throws PyValueError on anything CPython would reject.
 */
export function pyInt(text) {
  const stripped = pyStrip(text);
  if (!INT_LITERAL_RE.test(stripped)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyStrRepr(text)}`,
    );
