// Type converters usable as argparse `type=`. Each carries the name argparse
// uses in its "invalid <name> value" error message.

import { pyInt } from './pyint.mjs';

export const int = { name: 'int', fn: pyInt };

export const str = { name: 'str', fn: (value) => value };

export const float = {
  name: 'float',
  fn: (value) => {
    const parsed = Number(value.trim());
    if (value.trim() === '' || Number.isNaN(parsed) && !/^[+-]?nan$/i.test(value.trim())) {
      throw new TypeError('not a float');
    }
    return parsed;
  },
};

// Type converters usable as argparse `type=`. Each carries the name argparse
// uses in its "invalid <name> value" error message.

import { pyInt } from './pyint.mjs';

export const int = { name: 'int', fn: pyInt };

export const str = { name: 'str', fn: (value) => value };

export const float = {
  name: 'float',
  fn: (value) => {
    const text = pyStrip(value).replace(/(?<=[\d.])_(?=\d)/g, '');
    if (!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$|^[+-]?(?:inf(?:inity)?|nan)$/i.test(text)) {
      throw new PyValueError(`could not convert string to float: ${pyStrRepr(value)}`);
    }
    return Number(text.replace(/infinity$/i, 'Infinity').replace(/inf$/i, 'Infinity'));
  },
};

// Rendering of Python-ish values the way `print()` / `repr()` would.

import { PyBytes } from './bytes.mjs';
import { pyStrRepr } from './pyint.mjs';

/** CPython repr(). */
export function pyRepr(value) {
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'number') return Number.isInteger(value) ? String(value) : String(value);
  if (typeof value === 'string') return pyStrRepr(value);
  if (value instanceof PyBytes) return value.repr();
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) {
    const body = [...value.entries()]
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  return String(value);
}

/**
 * CPython str(). For every type this program prints (bytes, list, int) str()
 * and repr() agree; plain text is the one case that differs.
 */
export function pyStr(value) {
  if (typeof value === 'string') return value;
  return pyRepr(value);
}

/** Write one value plus a newline, exactly as print() does. */
export function pyPrint(value) {
  console.log(pyStr(value));
}

